choose.when:
SELECT cio.*, cp.contract_amount, cp.business_type, cio.project_id AS 'project.id', cp.NAME AS 'project.name', cp.short_name AS 'project.shortName', cp.serial_number AS 'project.serialNumber', cio.contract_waste_id AS 'contract_waste.id', cw.serial_number AS 'contract_waste.serial_number', cw.purchaser AS 'contract_waste.purchaser' FROM contract_invoice AS cio LEFT JOIN contract_project AS cp ON cio.project_id = cp.id AND cio.type = 1 LEFT JOIN sys_project_user_link AS pul ON cp.id = pul.project_id AND pul.bool_delete_enum = 0 LEFT JOIN contract_waste AS cw on cio.contract_waste_id = cw.id and cio.type = 2 LEFT JOIN sys_branch_company as bc on bc.id = cio.invoice_unit_id WHERE cio.bool_delete_enum = 0 and cio.type = #{type}
and pul.user_id = #{userId}
and cio.project_id = #{projectId}
and cio.contract_waste_id = #{contractWasteId}
and cio.invoice_unit_id = #{invoiceUnitId}
and cio.invoice_date >= #{startDate}
and cio.invoice_date <= #{endDate}
and cio.audit_status = #{auditStatus}
and (cp.name like concat('%',#{name},'%') or cp.short_name like concat('%',#{name},'%'))
and cw.purchaser like concat('%',#{name},'%')
and cp.business_type = #{businessType}
and bc.name like concat('%',#{contractSignBodyName},'%')
GROUP BY cio.id ORDER BY cio.audit_status ASC, cio.invoice_date DESC, cio.id DESC

choose.otherwise:
SELECT temp.* FROM ( SELECT cio.*, cp.contract_amount, cp.business_type, cio.project_id AS 'project.id', cp.name AS 'project.name', cp.short_name AS 'project.shortName', cp.serial_number AS 'project.serialNumber', cio.contract_waste_id AS 'contract_waste.id', cw.serial_number AS 'contract_waste.serial_number', cw.purchaser AS 'contract_waste.purchaser' FROM contract_invoice AS cio LEFT JOIN contract_project AS cp ON cio.project_id = cp.id AND cio.type = 1 LEFT JOIN sys_project_user_link AS pul ON cp.id = pul.project_id AND pul.bool_delete_enum = 0 LEFT JOIN contract_waste AS cw on cio.contract_waste_id = cw.id and cio.type = 2 LEFT JOIN sys_branch_company as bc on bc.id = cio.invoice_unit_id WHERE cio.bool_delete_enum = 0 and cio.type = 1
and cio.project_id = #{projectId}
and cio.invoice_unit_id = #{invoiceUnitId}
and cio.invoice_date >= #{startDate}
and cio.invoice_date <= #{endDate}
and cio.audit_status = #{auditStatus}
and (cp.name like concat('%',#{name},'%') or cp.short_name like concat('%',#{name},'%'))
and bc.name like concat('%',#{contractSignBodyName},'%')
GROUP BY cio.id UNION ALL SELECT cio.*, cp.contract_amount, cp.business_type, cio.project_id AS 'project.id', cp.name AS 'project.name', cp.short_name AS 'project.shortName', cp.serial_number AS 'project.serialNumber', cio.contract_waste_id AS 'contract_waste.id', cw.serial_number AS 'contract_waste.serial_number', cw.purchaser AS 'contract_waste.purchaser' FROM contract_invoice AS cio LEFT JOIN contract_project AS cp ON cio.project_id = cp.id AND cio.type = 1 LEFT JOIN sys_project_user_link AS pul ON cp.id = pul.project_id AND pul.bool_delete_enum = 0 LEFT JOIN contract_waste AS cw on cio.contract_waste_id = cw.id and cio.type = 2 LEFT JOIN sys_branch_company as bc on bc.id = cio.invoice_unit_id WHERE cio.bool_delete_enum = 0 and cio.type = 2
and cio.contract_waste_id = #{contractWasteId}
and cio.invoice_unit_id = #{invoiceUnitId}
and cio.invoice_date >= #{startDate}
and cio.invoice_date <= #{endDate}
and cio.audit_status = #{auditStatus}
and cw.purchaser like concat('%',#{name},'%')
and bc.name like concat('%',#{contractSignBodyName},'%')
GROUP BY cio.id ) AS temp ORDER BY temp.invoice_date DESC, temp.id DESC

mapper.select:
        SELECT
        IFNULL(sum(invoice_amount),0)
        FROM contract_invoice
        WHERE bool_delete_enum = 0
        
            AND audit_status = #{auditStatus}
        
        
            and project_id = #{projectId}

        SELECT
        IFNULL(SUM(tax),0)
        FROM contract_invoice
        WHERE bool_delete_enum = 0

        
            and project_id = #{projectId}
        

        
            and audit_status = #{auditStatus}

select * from contract_invoice where bool_delete_enum = 0
and project_id = #{projectId}
and remark like concat('%',#{remark},'%')
and invoice_type = #{collectionMode}
and collection_date >= DATE_FORMAT(#{startDate},'%Y-%m-%d')
and collection_date <= DATE_FORMAT(#{endDate},'%Y-%m-%d')
